/// <summary>
/// AVA/WEN 2024/05/17    AVA_011041_GeneralJournalReversal
/// </summary>
/// <param name = "args">Args</param>
void reversal(Args args)
{
    next reversal(args);

    if (args.dataset() == tableNum(GeneralJournalAccountEntry) && reverseSuccessful)
    {
        GeneralJournalAccountEntry locGeneralJournalAccountEntry = args.record();
        LedgerJournalTable locLedgerJournalTable = LedgerJournalTable::find(LedgerEntryJournal::find(GeneralJournalEntry::find(locGeneralJournalAccountEntry.GeneralJournalEntry).LedgerEntryJournal).JournalNumber);
        if (locLedgerJournalTable.AVAAllocationRefRecId)
        {
            LedgerJournalTable allocationLedgerJournalTable;
            allocationLedgerJournalTable = LedgerJournalTable::findByRecId(locLedgerJournalTable.AVAAllocationRefRecId, true);
            if (allocationLedgerJournalTable && !allocationLedgerJournalTable.AVAReversed)
            {
                ttsbegin;
                allocationLedgerJournalTable.AVAReversed = NoYes::Yes;
                allocationLedgerJournalTable.doUpdate();
                ttscommit;
            }
        }
    }
}
